#[allow(dead_code)]mod gen{include!("ramsey312_google_three_step.rs");pub fn go(){let args:Vec<_>=env::args().collect();let bs:Vec<_>=fs::read_to_string(&args[1]).unwrap().bytes().filter(|&b|b==48||b==49).collect();let a:Vec<M>=bs.chunks(52).map(|r|r.iter().enumerate().fold(0,|m,(i,&x)|m|(((x-48)as M)<<i))).collect();for(k,l)in fs::read_to_string(&args[2]).unwrap().lines().filter(|l|l.starts_with("L ")).enumerate(){let z:Vec<_>=l.split_whitespace().collect();let free=z[2].parse::<M>().unwrap();let h=((1<<52)-1)^free;let mut g=a.clone();for e in &z[5..]{let(i,j)=e.split_once(':').unwrap();let(i,j):(usize,usize)=(i.parse().unwrap(),j.parse().unwrap());g[i]^=1<<j;g[j]^=1<<i}let low=(0..52).filter(|&i|h>>i&1!=0&&(h&g[i]).count_ones()<11).fold(0,|m,i|m|1<<i);let mut es=vec![];sets(&g,h,11,0,&mut es);let mut req:Vec<_>=es.iter().map(|t|t&low).collect();req.sort_unstable();req.dedup();req.sort_by_key(|v|v.count_ones());let mut mins=vec![];for x in req{if !mins.iter().any(|y|x&y==*y){mins.push(x)}}let mut s=vec![];supports(&g,low,0,&mins,&mut s);assert_eq!(s.len(),z[4].parse().unwrap());print!("{k}");for x in s{print!(" {x}")}println!()}}}fn main(){gen::go()}
